// UpdateLoadBalancerJSONBody defines parameters for UpdateLoadBalancer.
type UpdateLoadBalancerJSONBody struct {
	// AclList Layer-7 ACL **rule definitions** (the match conditions). Only valid on an ALB - cannot coexist with `tcp_backend`. Each entry is paired 1:1 with an `acl_map` entry by `acl_name`.
	AclList *[]struct {
		// AclCondition HAProxy match condition. Built in the console from an ACL type (Path / Host / Query Parameter / HTTP Request / Source IP) and a comparison.
		//
		// Example: path_beg -i
		AclCondition UpdateLoadBalancerJSONBodyAclListAclCondition `json:"acl_condition"`

		// AclMatchingPath The value to match - a path, host, IP/CIDR, query-parameter value, or (for an HTTP-request ACL) a space-separated list of methods such as `GET POST`.
		//
		// Example: /api
		AclMatchingPath string `json:"acl_matching_path"`

		// AclName Unique name for this ACL rule; referenced by the matching `acl_map` entry.
		//
		// Example: acl-1
		AclName string `json:"acl_name"`
	} `json:"acl_list,omitempty"`

	// AclMap Maps named ACL rules (from `acl_list`) to the backend that should serve matching traffic. Only valid on an ALB.
	AclMap *[]struct {
		// AclBackend Name of the backend group that serves traffic matching this ACL.
		//
		// Example: backend-group-1
		AclBackend string `json:"acl_backend"`

		// AclConditionState When `true` (default) the rule routes to `acl_backend` on a match; `false` negates the condition.
		//
		// Example: true
		AclConditionState *bool `json:"acl_condition_state,omitempty"`

		// AclName Name of the ACL rule (must match an `acl_list[].acl_name`).
		//
		// Example: acl-1
		AclName string `json:"acl_name"`
	} `json:"acl_map,omitempty"`

	// Backends ALB backend groups (same item shape as create). Add, edit, or remove backends here. Empty for an NLB. Deleting a backend also prunes any `acl_map` entries that targeted it.
	Backends *[]struct {
		// BackendMode Example: http
		BackendMode *string `json:"backend_mode,omitempty"`

		// BackendSsl Example: false
		BackendSsl *bool `json:"backend_ssl,omitempty"`

		// Balance Example: source
		Balance *UpdateLoadBalancerJSONBodyBackendsBalance `json:"balance,omitempty"`

		// CheckUrl Example: /
		CheckUrl *string `json:"check_url,omitempty"`

		// DomainName Example: localhost
		DomainName *string `json:"domain_name,omitempty"`

		// HttpCheck Example: true
		HttpCheck *bool `json:"http_check,omitempty"`

		// Name Example: backend-group-1
		Name       *string `json:"name,omitempty"`
		NetworkId  *string `json:"network_id,omitempty"`
		ScalerId   *string `json:"scaler_id,omitempty"`
		ScalerPort *string `json:"scaler_port,omitempty"`
		Servers    *[]struct {
			// BackendIp Example: 10.2.3.4
			BackendIp *string `json:"backend_ip,omitempty"`

			// BackendName Example: C3-8GB-853
			BackendName *string `json:"backend_name,omitempty"`

			// BackendPort Example: 543
			BackendPort *int `json:"backend_port,omitempty"`
		} `json:"servers,omitempty"`

		// WebsocketTimeout WebSocket idle timeout (1-100s); send null (not empty string) to disable.
		//
		// Example: 60
		WebsocketTimeout *int `json:"websocket_timeout,omitempty"`
	} `json:"backends,omitempty"`

	// ClientTimeout Example: 61
	ClientTimeout *int `json:"client_timeout,omitempty"`

	// ConnectionTimeout Example: 61
	ConnectionTimeout *int `json:"connection_timeout,omitempty"`

	// DefaultBackend Backend that serves unmatched traffic. Must be empty if there are no `backends`.
	//
	// Example: backend-group-1
	DefaultBackend *string `json:"default_backend,omitempty"`

	// EnableBitninja Example: false
	EnableBitninja *bool `json:"enable_bitninja,omitempty"`

	// HttpKeepAliveTimeout Example: 61
	HttpKeepAliveTimeout *int `json:"http_keep_alive_timeout,omitempty"`

	// IsIpv6Attached Example: false
	IsIpv6Attached *bool `json:"is_ipv6_attached,omitempty"`

	// LbMode Frontend protocol (`HTTP`/`HTTPS`/`BOTH` for an ALB, `TCP` for an NLB).
	//
	// Example: HTTP
	LbMode string `json:"lb_mode"`

	// LbName Display name (changing it here renames the load balancer).
	//
	// Example: new-name-1
	LbName string `json:"lb_name"`

	// LbPort Listening port (string).
	//
	// Example: 80
	LbPort string `json:"lb_port"`

	// LbReserveIp Example:
	LbReserveIp *string `json:"lb_reserve_ip,omitempty"`

	// LbType Network scheme. `internal` requires a non-empty `vpc_list` and forbids `lb_reserve_ip`.
	//
	// Example: external
	LbType UpdateLoadBalancerJSONBodyLbType `json:"lb_type"`

	// NodeListType Example: D
	NodeListType UpdateLoadBalancerJSONBodyNodeListType `json:"node_list_type"`

	// PlanName Plan SKU. Changing it here is **not** how you upgrade - use Perform Load Balancer Action with `type: upgrade_plan` instead.
	//
	// Example: E2E-LB-2
	PlanName string `json:"plan_name"`

	// SecurityGroupId Example: 12345
	SecurityGroupId *int `json:"security_group_id,omitempty"`

	// ServerTimeout Example: 61
	ServerTimeout *int `json:"server_timeout,omitempty"`

	// SslContext TLS configuration (ALB only).
	SslContext *struct {
		// RedirectToHttps Example: false
		RedirectToHttps  *bool `json:"redirect_to_https,omitempty"`
		SslCertificateId *int  `json:"ssl_certificate_id,omitempty"`
	} `json:"ssl_context,omitempty"`

	// TcpBackend NLB TCP backend (same item shape as create). At most one entry. Mutually exclusive with `backends`.
	TcpBackend *[]interface{} `json:"tcp_backend,omitempty"`

	// VpcList VPC attachments (required for internal load balancers).
	VpcList *[]struct {
		// Ipv4Cidr Example: 10.1.2.3/23
		Ipv4Cidr *string `json:"ipv4_cidr,omitempty"`

		// NetworkId Example: 12345
		NetworkId *string `json:"network_id,omitempty"`

		// VpcName Example: VPC-261
		VpcName *string `json:"vpc_name,omitempty"`
	} `json:"vpc_list,omitempty"`
}

